# Final c1 rowwise decisions; directory/history rule derivations are in the accompanying notes.
import csv,json,pathlib
rows=json.loads(DATA)
p=pathlib.Path('A1/c1/part-2.stored.tsv')
existing=list(csv.DictReader(p.open(),delimiter='\t')) if p.exists() else []
seen={r['id'] for r in existing}
if not p.exists():p.write_text('\t'.join(rows[0].keys())+'\n')
for r in rows:
 if r['id'] in seen:continue
 with p.open('a') as f:csv.DictWriter(f,fieldnames=r.keys(),delimiter='\t',lineterminator='\n').writerow(r)
 seen.add(r['id'])
